settings.custom_liquid:
{% liquid
  assign show_widget_border = true
%}
<style>
  .showClose>div>div {
    display: block !important;
  }

  .span_nowrap {
    text-wrap: nowrap;
  }

  .delProduct {
    align-self: flex-start;
  }

  h6.accordion__title.sizechart_title {
    max-width: calc(100% - 1rem);
  }


  .price-combo {
    padding: 10px;
  }

  .tusokcombo-mixmatch {
    padding: 0.5rem;
    margin: 15px 0 15px 0;

      {% if show_widget_border %}

    border: 1px solid #f0f0f0;
    border-radius: 2px;

      {% endif %}

    width: 100%;
    background : #f0f0f0;
    transition: .2s ease-in-out;
  }

  .tusokcombo-mixmatch_heading {
    font-weight: 500;
    font-size: 24px;
    padding: 15px 0 0 15px;
    text-align: center;
  }

  .tusokcombo-mixmatch_pcs_div {
    display: none;
    font-size: small;
    text-align: -webkit-center;
    font-weight: bold;
  }

  .tusokcombo-mixmatch_X {
    font-size: small;
  }

  .tusokcombo-mixmatch_pcs {
    text-wrap: nowrap;
    font-size: small;
  }

  .tusokcombo-mixmatch_row_flex {
    display: flex;
    float: left;
    width: 100%;
  }

  .tusokcombo-mixmatch_row {

    padding: 10px;
    box-shadow: none;
    position: relative;
    float: left;
    width: 100%;
    background: white;
    margin-bottom: 10px;
    display: flex;
  }

  .tusokcombo-mixmatch_thumbnail {
    position: relative;
    -webkit-filter: none !important;
    filter: none !important;
    overflow: hidden;
    min-width: 30%;
    max-width: 30%;

    margin-right: 10px;
  }

  .tusokcombo-mixmatch_image {
    width: 100%;
  }

  .tusokcombo-mixmatch_caption {
    padding-top: 10px;
  }

  .tusokcombo-mixmatch_footer {

    text-align: left;
  }

  .tusokcombo-mixmatch_price {
    font-size: 1.6rem;
    line-height: calc(1 + .5 / var(--font-body-scale));
    letter-spacing: .13rem;
    color: rgb(var(--color-foreground));
  }

  .tusokcombo-mixmatch_compare {
    margin-left: 8px;
    text-decoration: line-through;
    color: #878787;
  }

  .tusokcombo-mixmatch_ATC {
    width: 100%;
    display: inline-block;
  }

  .tusokcombo-mixmatch_ATC:hover {
    border-color: black;
  }

  .tusokcombo-mixmatch_ATC:disabled {
    cursor: not-allowed;
  }

  .tusokcombo-mixmatch_error-message {
    color: red !important;
    margin: 0 !important;
    padding: 5px 10px;
  }

  .tusokcombo-mixmatch_hide {
    display: none;
  }

  .tusokcombo-mixmatch_soldout {
    border: 1px solid red;
    color: red;
  }

  @media only screen and (max-width: 500px) {

    .tusokcombo-mixmatch_thumbnail,
    .tusokcombo-mixmatch_caption,
    .tusokcombo-mixmatch_footer-left,
    .tusokcombo-mixmatch_footer-right {}

  }

  .tusokcombo-mixmatch_title {
    text-align: left;
    font-size: small;
    color: #333;
  }

  .deleteProd {
    color: red;
    cursor: pointer;
  }

  .tusokcombo-mixmatch_titlebar {
    display: flex;
    width: 100%;
    align-items: center;
  }

  .tusokcombo-mixmatch_sizechart {
    white-space: nowrap;
    color: #007BFF;
    text-decoration: none;
  }

  span.addProductText {
    font-size: small;
    display: inline-block;
    padding-left: 5px;
  }

  .addProduct {
    color: blue;
    cursor: pointer;
    text-align: center;
    align-self: flex-end;
    display: flex;
    align-items: center;
    padding: 5px;
  }
  button.addProduct, button.delProduct {
    background: none;
    border: none;
  }

  .tusokcombo-mixmatch_right {
    flex-grow: 2;
    display: flex;
    flex-direction: column;
  }
  {% if product.metafields.custom.iscomboproduct != true %}
  .forset {
    display: none;
  }
  {% endif %}
</style>
<div class="tusokcombo-mixmatch" id="tusokcombo-mixmatch_{{ product.id }}">
  <div class="tusokcombo-mixmatch_footer">
    <div class="tusokcombo-mixmatch_footer-left">
      <div class="tusokcombo-mixmatch_compare tusokcombo-mixmatch_hide"></div>
    </div>
  </div>
  <div class="tusokcombo-mixmatch_body">
    {% assign soldout = false %}
    {% assign is_combo = false %}
    {% if product.metafields.custom.iscomboproduct %}
      {% assign is_combo = true %}
      {% assign loop_items = product.metafields.combo %}
    {% else %}
      {% assign loop_items = product.handle | split: '|||' %}
    {% endif %}

    {% for item in loop_items %}
      {% if is_combo %}
        {% assign handle = item[1] %}
      {% else %}
        {% assign handle = item %}
      {% endif %}
      {% assign selectPlaceholder = 'Select variant' %}
      {% assign sequence = 0 %}
      {% assign p = all_products[handle] %}
      {% if p.available == false%}
        {% assign soldout = true %}
      {% endif %}

      <div class="tusokcombo-mixmatch_row {% unless forloop.last %}has-plus{% endunless %}">
        {% if is_combo %}
          <div class="tusokcombo-mixmatch_thumbnail">
            <img class="tusokcombo-mixmatch_image" alt="{{ p.title }}" src="{{ p.featured_image | image_url: width: 300 }}">
            <div class="tusokcombo-mixmatch_pcs_div">
              <span class="tusokcombo-mixmatch_X"> Quantity : </span>
              <span class="tusokcombo-mixmatch_pcs"> 1 </span>
            </div>
          </div>
        {% endif %}

        <div class="tusokcombo-mixmatch_right">
          {% if is_combo %}
            <div class="tusokcombo-mixmatch_title">{{ p.title }}</div>
          {% endif %}
          {% assign product_type = p.type %}
          {% assign size_chart_id = '' %}
          {% case product_type %}
            {% when "Kids's Tshirt" %}
              {% assign size_chart_id = 'popup-size-chart-kids-unisex-t-shirt' %}
            {% when "Men's Shirts", 'Shirts' %}
              {% assign size_chart_id = 'popup-size-chart-half-sleeve-shirt' %}
            {% when "Women's Gown" %}
              {% assign size_chart_id = 'popup-size-chart-womens-gown' %}
            {% when "Women's Dresses" %}
              {% assign size_chart_id = 'popup-size-chart-women-dress' %}
       {% when "Girl's Smocked Strappy Frock" %}
              {% assign size_chart_id = "popup-size-chart-girls-smocked-strappy-dress" %}
         {% when "Women's Smocked Strappy Dress" %}
              {% assign size_chart_id = "popup-size-chart-womens-smocked-strappy-dress" %}
            {% when "Women Tshirt" %}
              {% assign size_chart_id = "popup-size-chart-womens-tshirt-quote" %}
            {% when "Girls Tshirt" %}
              {% assign size_chart_id = "popup-size-chart-girls-t-shirt-quote" %}
            {% when "Women's Shirts" %}
              {% assign size_chart_id = 'popup-size-chart-womens-front-knot-shirt' %}
            {% when "Women's Tops" %}
              {% assign size_chart_id = 'popup-size-chart-womens-top' %}
            {% when "Women's Puff Sleeve Tops" %}
              {% assign size_chart_id = 'popup-size-chart-womens-puff-sleeve-tops' %}
            {% when "Women's Puffed Sleeve Knee Long Dresses" %}
              {% assign size_chart_id = 'popup-size-chart-puffed-shoulder-knee-length-womens-dress' %}
            {% when "Anarkali Women's Collar Dress with Belt" %}
              {% assign size_chart_id = 'popup-size-chart-anarkali-womens-collar-dress-with-belt' %}
            {% when "Girls Cordset" %}
              {% assign size_chart_id = 'popup-size-chart-girls-co-ord-set' %}
            {% when "Women's Button Down Dresses" %}
              {% assign size_chart_id = 'popup-size-chart-womens-button-down-dress' %}
            {% when "Women's Co-ord Set" %}
              {% assign size_chart_id = 'popup-size-chart-womens-co-ord-set' %}
            {% when 'Mens Short Kurta' %}
              {% assign size_chart_id = 'popup-size-chart-mens-full-sleeve-short-kurta' %}
            {% when "Men's Full Sleeve Shirts" %}
              {% assign size_chart_id = 'popup-size-chart-mens-full-sleeve-shirts' %}
            {% when 'Girls Frock' %}
              {% assign size_chart_id = 'popup-size-chart-girls-frock' %}
            {% when 'Mens Tshirt' %}
              {% assign size_chart_id = 'popup-size-chart-mens-tshirt' %}
            {% when 'Boy Tshirt' %}
              {% assign size_chart_id = 'popup-size-chart-boys-t-shirt' %}
            {% when 'Girls Tshirt Dress' %}
              {% assign size_chart_id = 'popup-size-chart-girls-t-shirt' %}
            {% when 'Women Tshirt Dress' %}
              {% assign size_chart_id = 'popup-size-chart-womens-tshirt' %}
          {% endcase %}

            {% if size_chart_id != '' %}
              <a
                class="sizeChartButton"
                href="#"
                data-sizechart="{{ size_chart_id }}"
              ><svg
                  class="icon icon-accordion color-foreground-text"
                  aria-hidden="true"
                  focusable="false"
                  role="presentation"
                  xmlns="http://www.w3.org/2000/svg"
                  width="16"
                  height="16"
                  viewBox="0 0 16 16"
                >
                  <path d="M14.93 4.11L12.1 1.28a1 1 0 00-1.41 0L6.8 5.17.78 11.18a1 1 0 000 1.42l2.82 2.82a1 1 0 001.42 0l9.9-9.9a1 1 0 000-1.4zm-10.6 10.6L1.48 11.9l1.41-1.41 1.06 1.06a.5.5 0 00.71-.71L3.61 9.77l1.42-1.42 1.05 1.06a.5.5 0 00.71-.7L5.73 7.65l1.42-1.42L8.2 7.3c.2.2.5.2.7 0s.2-.5 0-.7L7.85 5.53 9.27 4.1l1.06 1.06a.5.5 0 00.71-.7L9.98 3.4 11.39 2l2.83 2.83-9.9 9.9z"></path>
                </svg><h6 class="h6 accordion__title sizechart_title" data-sizechart="{{ size_chart_id }}">
                  Size Chart
                </h6>
              </a>
            {% endif %}

            {% capture variant_options %}
                <option value="" disabled selected>{{ selectPlaceholder }}</option>

              {% if p.has_only_default_variant %}
                <option
                  value="{{ p.variants[0].id }}"
                  {% comment %} data-image="" {% endcomment %}
                  data-price="{{ p.variants[0].price }}"
                  data-available="{{ p.variants[0].available }}"
                  data-compare="{% if p.variants[0].compare_at_price %}{{ p.variants[0].compare_at_price  }}{% else %}{{ p.variants[0].price }}{% endif %}"
                  {% if p.available == false %}
                    disabled
                  {% endif %}

                >
                  {{ p.title -}}
                  {%- if p.available == false %} - {{ 'products.product.sold_out' | t }}{% endif %}
                </option>
              {% else %}
                {% for v in p.variants %}
                  <option
                    value="{{ v.id }}"
                    {% comment %} data-image="{{ v.image.src | image_url: width: 300 }}" {% endcomment %}
                    data-price="{{ v.price }}"
                    data-available="{{ v.available }}"
                    data-compare="{% if v.compare_at_price %}{{ v.compare_at_price  }}{% else %}{{ v.price }}{% endif %}"
                    {% if v.available == false %}
                      disabled
                    {% endif %}
                  >
                    {{ v.title -}}
                    {%- if v.available == false %}
                      - {{ 'products.product.sold_out' | t }}
                    {% else %}
                      - {{ v.price | money_with_currency }}
                    {% endif %}
                  </option>
                {% endfor %}
              {% endif %}
            {% endcapture %}

            <div class="tusokcombo-mixmatch_caption">
              <div class="tusokcombo-mixmatch_select_wrap select">
                <select
                  {% comment %} value="{{ defaultVariantId }}" {% endcomment %}

                  class="tusokcombo-mixmatch_select select__select {% if p.available == false %}tusokcombo-mixmatch_soldout{% endif %}"
                  required
                  onChange="tusokcomboVariantChange(this)"
                >
                  {{ variant_options }}
                </select>
                <svg
                  aria-hidden="true"
                  focusable="false"
                  role="presentation"
                  class="icon icon-caret"
                  viewBox="0 0 10 6"
                >
                    <path fill-rule="evenodd" clip-rule="evenodd" d="M9.354.646a.5.5 0 00-.708 0L5 4.293 1.354.646a.5.5 0 00-.708.708l4 4a.5.5 0 00.708 0l4-4a.5.5 0 000-.708z" fill="currentColor">
                  </path>
                </svg>
              </div>
            </div>
          {% if is_combo %}
            <button type="button" class="delProduct deleteProd" onclick="deleteProduct(this)">x Remove</button>

            <template id="tpl-{{ p.id }}">
              <div class="tusokcombo-mixmatch_caption showClose">
                <div class="tusokcombo-mixmatch_select_wrap select">
                  <select class="tusokcombo-mixmatch_select select__select {% if p.available == false %}tusokcombo-mixmatch_soldout{% endif %}"
                    required
                    onChange="tusokcomboVariantChange(this)">
                    {{ variant_options }}
                  </select>
                  <svg aria-hidden="true" focusable="false" role="presentation" class="icon icon-caret" viewBox="0 0 10 6">
                    <path fill-rule="evenodd" clip-rule="evenodd" d="M9.354.646a.5.5 0 00-.708 0L5 4.293 1.354.646a.5.5 0 00-.708.708l4 4a.5.5 0 00.708 0l4-4a.5.5 0 000-.708z" fill="currentColor"></path>
                  </svg>
                </div>
              </div>
              <button type="button" class="delProduct deleteProd" onclick="deleteProduct(this)">x Remove</button>
            </template>

            <button type="button" class="addProduct" onclick="addComboProduct({{ p.id }}, this)">
              <span>
                <svg width="22px" height="22px" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <rect width="24" height="24" fill="white"/>
                  <path fill-rule="evenodd" clip-rule="evenodd" d="M13 9C13 8.44772 12.5523 8 12 8C11.4477 8 11 8.44772 11 9V11H9C8.44772 11 8 11.4477 8 12C8 12.5523 8.44772 13 9 13H11V15C11 15.5523 11.4477 16 12 16C12.5523 16 13 15.5523 13 15V13H15C15.5523 13 16 12.5523 16 12C16 11.4477 15.5523 11 15 11H13V9ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12Z" fill="blue"/>
                </svg>
              </span>
              <span class="addProductText">Add More</span>
            </button>
          {% endif %}
        </div>
      </div>
    {% endfor %}


    <div class="price-combo">
      <div class="tusokcombo-mixmatch_price"></div>
      <div class="caption rte">{{ 'products.product.include_taxes' | t }}</div>

      <p class="tusokcombo-mixmatch_error-message tusokcombo-mixmatch_hide"></p>
    </div>
    <button
      type="button"
      class="tusokcombo-mixmatch_ATC button button--full-width button--primary"
      onClick="{% if soldout == false %}tusokcomboATCSubmit(){% endif %}"
    >
      {% if soldout -%}
        {{- 'products.product.sold_out' | t -}}
      {%- else -%}
        {{- 'products.product.add_to_cart' | t -}}
      {%- endif %}
    </button>
  </div>
  <script>
             const MIXMATCH_IMG_SELECT = '#tusokcombo-mixmatch_{{ product.id }} .tusokcombo-mixmatch_image';
             const MIXMATCH_CHILD_SELECT = '.tusokcombo-mixmatch_select';
             const MIXMATCH_PRICE_SELECT = '#tusokcombo-mixmatch_{{ product.id }} .tusokcombo-mixmatch_price';
             const MIXMATCH_COMPARE_SELECT = '#tusokcombo-mixmatch_{{ product.id }} .tusokcombo-mixmatch_compare';
             const MIXMATCH_ATC = '#tusokcombo-mixmatch_{{ product.id }} .tusokcombo-mixmatch_ATC';
             const MIXMATCH_QUANTITY = '[name="quantity"]';

            document.addEventListener('click', function (e) {
                const target = e.target.closest('[data-sizechart]');
                if (!target) return;

                e.preventDefault();
                const id = target.getAttribute('data-sizechart');
                const el = document.getElementById(id);
                if (el) el.style.display = 'block';
            });

             function tusokcomboMoney(price) {
               const format = '{{ 0 | money_with_currency }}';
               return format.replace('0.00', price.toFixed(2));
             }

             function tusokcomboVariantChange(e) {
               {% if show_child_image %}
               tusokcomboUpdateChildImage(e);
               {% endif %}
               tusokcomboUpdateBundlePrice();
               tusokcomboEnableATCforSubmission();
             }

             function tusokcomboUpdateChildImage(e) {
               const img_src = e.options[e.selectedIndex].getAttribute('data-image');

               if (img_src && img_src.indexOf('no-image') == -1) {
                 const imgEle = e.parentNode.parentNode.parentNode.querySelector(MIXMATCH_IMG_SELECT);
                 if (imgEle) {
                   imgEle.src = img_src;
                 }
               }
             }

              function updatePcs(ele2,n) {
                 var x = Number(n)
                  ele2.previousElementSibling.lastElementChild.lastElementChild.innerHTML = ele2.childElementCount-3-x;
              }


             function tusokcomboUpdateBundlePrice() {
                let price = 0;
                let compare = 0;
                let selectedCount = 0; // New counter for valid selections
                const childs = document.querySelectorAll(MIXMATCH_CHILD_SELECT);

                for (let i = 0; i < childs.length; i++) {
                  const obj = childs[i];
                  const selectedOption = obj.options[obj.selectedIndex];

                  // Check if a valid variant is selected (not the placeholder)
                  if (selectedOption && selectedOption.value !== "") {
                    price += (selectedOption.getAttribute('data-price') / 100);
                    compare += (selectedOption.getAttribute('data-compare') / 100);
                    selectedCount++; // Increment only if a variant is chosen
                  }
                }

                // Update the Price Display
                const priceContainer = document.querySelector(MIXMATCH_PRICE_SELECT);

                // Create the "X pieces" text based on selectedCount
                let countText = selectedCount > 0 
                  ? " <span class='forset'>(For set of " + selectedCount + " " + (selectedCount === 1 ? "piece" : "pieces") + ")</span>" 
                  : "";

                priceContainer.innerHTML = tusokcomboMoney(price) + countText;

                // Handle Compare Price Visibility
                const compareEle = document.querySelector(MIXMATCH_COMPARE_SELECT);
                if (price < compare) {
                  compareEle.classList.remove('tusokcombo-mixmatch_hide');
                } else {
                  compareEle.classList.add('tusokcombo-mixmatch_hide');
                }
              }

              function tusokcomboEnableATCforSubmission() {
                const childs = document.querySelectorAll(MIXMATCH_CHILD_SELECT);
                let atLeastOneSelected = false;

                childs.forEach(select => {
                  if (select.value && select.value !== "") {
                    atLeastOneSelected = true;
                  }
                });

                const atcButton = document.querySelector(MIXMATCH_ATC);
                if (atcButton) {
                  // Disable ONLY if nothing is selected. Enable if at least one is picked.
                  atcButton.disabled = !atLeastOneSelected;
                  atcButton.style.opacity = !atLeastOneSelected ? "0.5" : "1";

                  // Optional: Update button text to be helpful
                  if (!atLeastOneSelected) {
                    atcButton.innerText = "Select at least one variant";
                  } else {
                    atcButton.innerText = "{{ 'products.product.add_to_cart' | t }}";
                  }
                }
              }

             function tusokcomboShowErrorMessage(message) {
               const el = document.querySelector('.tusokcombo-mixmatch_error-message');
               el.innerText = message;
               el.classList.remove('tusokcombo-mixmatch_hide');

               setTimeout(function() {
                 el.innerText = '';
                 el.classList.add('tusokcombo-mixmatch_hide');
               }, 4000);
             }

             function tusokcomboSyncImages() {
               const selectedVariants = document.querySelectorAll(MIXMATCH_CHILD_SELECT);
               for (let i = 0; i < selectedVariants.length; i++) {
                 const e = selectedVariants[i];
                 const img_src = e.options[e.selectedIndex].getAttribute('data-image');
                 if (img_src && img_src.indexOf('no-image') == -1) {
                   const imgEle = e.parentNode.parentNode.parentNode.querySelector(MIXMATCH_IMG_SELECT);
                   imgEle.src = img_src;
                 }
               }
             }

             function addComboProduct(id, ele) {
                const tpl = document.getElementById('tpl-' + id);
                if (!tpl) return;
                const clone = tpl.content.cloneNode(true);
                // Insert before the button. The template contains both the select div and the remove button.
                ele.parentElement.insertBefore(clone, ele);

                tusokcomboUpdateBundlePrice();
                updatePcs(ele.parentElement, 0);
                tusokcomboEnableATCforSubmission();
             }

          function deleteProduct(elen){
              const ele = elen.previousElementSibling
              const ele2 = ele.parentElement;
              updatePcs(ele2,1);
              ele.remove();
              elen.remove();
              tusokcomboUpdateBundlePrice();
              tusokcomboEnableATCforSubmission();
          }



             function tusokcomboATCSubmit() {
                const selectedVariants = document.querySelectorAll(MIXMATCH_CHILD_SELECT);
                const nodes = Array.prototype.slice.call(selectedVariants, 0);
                let cpqty = document.querySelector(MIXMATCH_QUANTITY);
                cpqty = cpqty ? parseInt(cpqty.value) : 1;

                // This filter is key: it ignores any dropdown that says "Select variant"
                let variantIds = nodes
                  .map(e => e.value)
                  .filter(id => id && id !== ""); 

                if (variantIds.length === 0) {
                  tusokcomboShowErrorMessage("Please select at least one item.");
                  return;
                }

                // ... rest of your existing fetch logic ...
                let meta = {};
                variantIds.forEach(id => {
                  meta[id] = (meta[id] || 0) + cpqty;
                });

                let items = [];
                for (let key in meta) {
                  items.push({ id: parseInt(key), quantity: meta[key] });
                }

               let tusokcomboForm = {
                 items
               };

               fetch('/cart/add.js', {
                 method: 'POST',
                 headers: {
                   'Content-Type': 'application/json'
                 },
                 body: JSON.stringify(tusokcomboForm)
               })
               .then(response => {
                 return response.json();
               })
               .then(data => {
                 if (data.description) {
                   tusokcomboShowErrorMessage(data.description);
                 } else {
                   window.location.href = '/cart';
                 }
               })
               .catch((error) => {
                 console.error('Error:', error);
               });
             }


             document.addEventListener("DOMContentLoaded", function(event) {
               console.info('Combowise: Dom loaded');

               // Trigger on change so price and images get updated
               document.querySelector(MIXMATCH_CHILD_SELECT).dispatchEvent(new Event('change'));

               {% if show_child_image %}
               // sync images
               tusokcomboSyncImages();
               {% endif %}
             });
  </script>
